CREATE TABLE IF NOT EXISTS demo_searches (id INTEGER PRIMARY KEY AUTOINCREMENT, locality TEXT NOT NULL, bhk INTEGER NOT NULL, max_rent INTEGER NOT NULL, pets_required INTEGER NOT NULL, alerts_consent INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS demo_viewings (id INTEGER PRIMARY KEY AUTOINCREMENT, listing_id TEXT NOT NULL, requested_time TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'demo_request_not_confirmed', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (phone TEXT PRIMARY KEY, name TEXT, prefs TEXT NOT NULL DEFAULT '{}', whatsapp_ok INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS listings_cache (id TEXT PRIMARY KEY, source TEXT NOT NULL, data TEXT NOT NULL, fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wishlist (id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT NOT NULL, listing_id TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(phone, listing_id));
CREATE TABLE IF NOT EXISTS alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT NOT NULL, criteria TEXT NOT NULL, channel TEXT NOT NULL DEFAULT 'whatsapp', call_if_urgent INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, last_run TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alert_seen (alert_id INTEGER NOT NULL, listing_id TEXT NOT NULL, PRIMARY KEY(alert_id, listing_id));
CREATE TABLE IF NOT EXISTS visits (id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT NOT NULL, listing_id TEXT NOT NULL, owner_name TEXT, owner_phone TEXT NOT NULL, requested_time TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', channel TEXT, notes TEXT, escalated INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, direction TEXT NOT NULL, channel TEXT NOT NULL, addr TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL, provider_id TEXT, ref_type TEXT, ref_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deals (id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT NOT NULL, listing_id TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'shortlisted', terms TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(phone, listing_id));
